// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia, "Times New Roman", serif';
var TEAL = '#1a7f9e', WALLRED = '#dd2222', GREEN = '#178a3a';
var RANGE = 565, PEAK = 155;

function hOf(x) { if (x < 0 || x > RANGE) return 0; return 4 * PEAK * x * (RANGE - x) / (RANGE * RANGE); }

var bb = { dist: 200, wallX: 400, wallH: 12, sampled: false, flying: false, flyX: 0, t0: 0, chart: null, drag: false };

var curvePts = [], i;
for (i = 0; i <= 160; i++) { var cx = RANGE * i / 160; curvePts.push({ x: cx, y: hOf(cx) }); }
var sampPts = [];
for (i = 0; i < 12; i++) { sampPts.push({ x: i * 50, y: hOf(i * 50) }); }

function kOf(c) {
  var w = (c.chartArea ? c.chartArea.width : c.width) || 400;
  var h = (c.chartArea ? c.chartArea.height : c.height) || 300;
  var k = Math.min(w, h) / 330;
  return Math.max(0.58, Math.min(1.25, k));
}
function PX(v) { return bb.chart.scales.x.getPixelForValue(v); }
function PY(v) { return bb.chart.scales.y.getPixelForValue(v); }

function ht(ctx, s, x, y, size, align, base, color, weight) {
  ctx.font = (weight ? weight + ' ' : '') + size.toFixed(1) + 'px ' + SERIF;
  ctx.textAlign = align || 'left'; ctx.textBaseline = base || 'alphabetic';
  ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2, size * 0.3); ctx.strokeStyle = '#fff';
  ctx.strokeText(s, x, y);
  ctx.fillStyle = color || '#000'; ctx.fillText(s, x, y);
}
function head(ctx, x, y, ang, size, color) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-size, size * 0.45);
  ctx.lineTo(-size * 0.7, 0); ctx.lineTo(-size, -size * 0.45); ctx.closePath();
  ctx.fillStyle = color; ctx.fill(); ctx.restore();
}
function tw(ctx, s, size, weight) {
  ctx.font = (weight ? weight + ' ' : '') + size.toFixed(1) + 'px ' + SERIF;
  return ctx.measureText(s).width;
}

/* ---------- overlay drawing ---------- */
function drawAxes(ctx, area, k) {
  var y0 = PY(0), x0 = PX(0), s = 8 * k;
  ctx.save(); ctx.setLineDash([]); ctx.strokeStyle = '#000'; ctx.lineWidth = Math.max(1.2, 1.6 * k);
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(area.right + 13 * k, y0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, area.top - 11 * k); ctx.stroke();
  head(ctx, area.right + 16 * k, y0, 0, s, '#000');
  head(ctx, x0, area.top - 14 * k, -Math.PI / 2, s, '#000');
  ctx.restore();
}
function drawCurveArrows(ctx, k) {
  var xs = [55, 150, 385, 470, 558], j;
  for (j = 0; j < xs.length; j++) {
    var x = xs[j], d = 4;
    var ax = PX(x), ay = PY(hOf(x));
    var bx = PX(x + d), by = PY(hOf(x + d));
    head(ctx, ax, ay, Math.atan2(by - ay, bx - ax), 8.5 * k, TEAL);
  }
}
function drawOpenCircle(ctx, k) {
  var x = 195, cx = PX(x), cy = PY(hOf(x)), r = 6.5 * k;
  ctx.save(); ctx.beginPath(); ctx.arc(cx, cy, r, 0, 6.2832);
  ctx.fillStyle = '#fff'; ctx.fill();
  ctx.lineWidth = Math.max(1.2, 1.8 * k); ctx.strokeStyle = '#e08a2e'; ctx.stroke(); ctx.restore();
}
function drawWall(ctx, area, k) {
  var w = Math.max(5, 8 * k), x = PX(bb.wallX);
  var yTop = PY(bb.wallH), yBot = PY(0);
  ctx.save(); ctx.fillStyle = WALLRED;
  ctx.fillRect(x - w / 2, yTop, w, yBot - yTop);
  ctx.restore();
}
function drawMarker(ctx, area, k) {
  var d = bb.dist, y = hOf(d), mx = PX(d), my = PY(y);
  ctx.save();
  ctx.setLineDash([4 * k, 4 * k]); ctx.lineWidth = Math.max(1, 1.2 * k); ctx.strokeStyle = '#9aa0a6';
  ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(mx, PY(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(PX(0), my); ctx.stroke();
  ctx.setLineDash([]);
  ctx.beginPath(); ctx.arc(mx, my, 5.2 * k, 0, 6.2832);
  ctx.fillStyle = TEAL; ctx.fill(); ctx.lineWidth = 1.6 * k; ctx.strokeStyle = '#fff'; ctx.stroke();
  // callout
  var txt = '(' + d.toFixed(0) + ' ft, ' + y.toFixed(0) + ' ft)';
  var fs = 11.5 * k, pad = 4 * k;
  var wTxt = tw(ctx, txt, fs) + pad * 2, hTxt = fs * 1.55;
  var bx = mx + 12 * k, by = my - 14 * k - hTxt;
  if (bx + wTxt > area.right - 2) bx = mx - 12 * k - wTxt;
  if (by < area.top + 2) by = my + 14 * k;
  ctx.fillStyle = 'rgba(255,255,255,0.92)'; ctx.strokeStyle = '#b9c0c7'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.rect(bx, by, wTxt, hTxt); ctx.fill(); ctx.stroke();
  ht(ctx, txt, bx + pad, by + hTxt / 2 + fs * 0.35, fs, 'left', 'alphabetic', '#123');
  ctx.restore();
}
function drawBall(ctx, k) {
  var x = bb.flyX, cx = PX(x), cy = PY(hOf(x));
  ctx.save();
  ctx.beginPath(); ctx.arc(cx, cy, 7 * k, 0, 6.2832);
  ctx.fillStyle = '#fff'; ctx.fill();
  ctx.lineWidth = 2.2 * k; ctx.strokeStyle = TEAL; ctx.stroke();
  ctx.restore();
}
function drawTable(ctx, area, k) {
  var fs = Math.max(8, 10.5 * k), rowH = fs * 1.38;
  var rows = sampPts.slice();
  var maxH = (PY(168) - area.top) - 6;
  if (rowH * (rows.length + 1) + 8 > maxH) rows = rows.filter(function (p, idx) { return idx % 2 === 0; });
  var w = Math.max(tw(ctx, 'd (ft)  h (ft)', fs) + 26 * k, 74 * k);
  var hgt = rowH * (rows.length + 1) + 8;
  var x1 = area.right - w - 4, y1 = area.top + 3;
  ctx.save();
  ctx.fillStyle = 'rgba(255,255,255,0.94)'; ctx.strokeStyle = '#b9c0c7'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.rect(x1, y1, w, hgt); ctx.fill(); ctx.stroke();
  ht(ctx, 'd (ft)', x1 + 8 * k, y1 + rowH, fs, 'left', 'alphabetic', '#333', 'bold');
  ht(ctx, 'h (ft)', x1 + w - 8 * k, y1 + rowH, fs, 'right', 'alphabetic', '#333', 'bold');
  ctx.strokeStyle = '#d5dade'; ctx.beginPath();
  ctx.moveTo(x1 + 5, y1 + rowH + 3); ctx.lineTo(x1 + w - 5, y1 + rowH + 3); ctx.stroke();
  for (var r = 0; r < rows.length; r++) {
    var yy = y1 + rowH * (r + 2);
    ht(ctx, rows[r].x.toFixed(0), x1 + 8 * k, yy, fs, 'left', 'alphabetic', '#123');
    ht(ctx, rows[r].y.toFixed(0), x1 + w - 8 * k, yy, fs, 'right', 'alphabetic', TEAL);
  }
  ctx.restore();
  return { l: x1, t: y1, r: x1 + w, b: y1 + hgt };
}
function drawClearance(ctx, area, k, tableBox) {
  var hw = hOf(bb.wallX);
  var landed = bb.wallX > RANGE;
  var clears = !landed && hw > bb.wallH;
  var col = clears ? GREEN : WALLRED;
  var xl = PX(bb.wallX) + 11 * k;
  ctx.save();
  if (!landed) {
    ctx.setLineDash([5 * k, 4 * k]); ctx.lineWidth = Math.max(1, 1.4 * k); ctx.strokeStyle = col;
