  { title: 'Does it clear the wall?', narration: 'The wall stands at 400 ft. Move the marker there and compare: the ball is roughly 140 ft up while the fence is only 12 ft — an easy home run.', state: { viewMode: 'Smooth path', distanceAlongPath: 400, wallPosition: 400, wallHeight: 12 } },
  { title: 'Push the wall out', narration: "Slide the wall toward 560 ft. As the curve dives back to the axis the clearance shrinks and eventually the badge flips to 'HITS WALL' — the question is always a comparison of two heights at one x.", state: { viewMode: 'Smooth path', distanceAlongPath: 555, wallPosition: 550, wallHeight: 12 } },
  { title: 'Same arc, as data', narration: 'Switch to sampled points: the smooth path becomes a set of (distance, height) pairs on the grid. The table and the curve carry identical information about the flight.', state: { viewMode: 'Sampled points', distanceAlongPath: 290, wallPosition: 400, wallHeight: 12 } }
];
var stepIdx = 0;
function setSlider(id, v, fn) {
  var el = document.getElementById(id + 'Input');
  if (!el) return;
  el.value = v;
  var out = document.getElementById(id + 'Val');
  if (out) out.value = v;
  fn(+v);
}
function applyStep(i, userInit) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  var cb = document.getElementById('viewModeInput');
  cb.checked = (s.state.viewMode === 'Sampled points');
  toggle_viewMode(cb.checked);
  setSlider('wallPosition', s.state.wallPosition, update_wallPosition);
  setSlider('wallHeight', s.state.wallHeight, update_wallHeight);
  setSlider('distanceAlongPath', s.state.distanceAlongPath, update_distanceAlongPath);
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  if (userInit && s.play && !bb.flying) trigger_flight();
}
function nextStep() { applyStep(stepIdx + 1, true); }
function prevStep() { applyStep(stepIdx - 1, true); }

applyStep(0, false);
document.addEventListener('fig-resize', function () { bb.chart.resize(); });
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
