</span>
<span style="display:block;border-top:1px solid #dcdfe3;margin:2px 0 0"></span>
<label>Distance from hitter (ft): <output id="distanceAlongPathVal">200</output>
  <input id="distanceAlongPathInput" type="range" min="0" max="570" step="5" value="200"
    oninput="document.getElementById('distanceAlongPathVal').value=this.value;update_distanceAlongPath(+this.value)"></label>
