Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font:600 12px Georgia,serif">Guided demo</span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;min-height:78px"></span>
<span style="display:flex;gap:8px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px"></span>
  <button onclick="nextStep()">▶</button>
</span>
<span style="display:block;border-top:1px solid #dcdfe3;margin:2px 0 0"></span>
<label>Distance from hitter (ft): <output id="distanceAlongPathVal">200</output>
  <input id="distanceAlongPathInput" type="range" min="0" max="570" step="5" value="200"
    oninput="document.getElementById('distanceAlongPathVal').value=this.value;update_distanceAlongPath(+this.value)"></label>
<label>Outfield wall distance (ft): <output id="wallPositionVal">400</output>
  <input id="wallPositionInput" type="range" min="100" max="580" step="10" value="400"
    oninput="document.getElementById('wallPositionVal').value=this.value;update_wallPosition(+this.value)"></label>
<label>Wall height (ft): <output id="wallHeightVal">12</output>
  <input id="wallHeightInput" type="range" min="5" max="60" step="1" value="12"
    oninput="document.getElementById('wallHeightVal').value=this.value;update_wallHeight(+this.value)"></label>
<label><input id="viewModeInput" type="checkbox" onchange="toggle_viewMode(this.checked)"> Sampled points view</label>
<button id="flightBtn" onclick="trigger_flight()">▶ Play ball flight</button>
<span id="readout" style="display:block;font-size:11px;line-height:1.45;font-family:Georgia,serif;color:#333"></span>
<span style="display:block;font-size:10px;color:#666;line-height:1.4">Tip: hover the curve, the marker or the red wall; drag the teal dot along the arc.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia, "Times New Roman", serif';
var TEAL = '#1a7f9e', WALLRED = '#dd2222', GREEN = '#178a3a';
var RANGE = 565, PEAK = 155, TAIL = 578;

function hRaw(x) { return 4 * PEAK * x * (RANGE - x) / (RANGE * RANGE); }
function hOf(x) { if (x < 0 || x > RANGE) return 0; return hRaw(x); }

var bb = {
  dist: 200, wallX: 400, wallH: 12, sampled: false,
  flying: false, flyX: 0, t0: 0, chart: null, drag: false, touched: false
};

var CH = null;                       /* current chart passed in by the plugin */
function PX(v) { return CH.scales.x.getPixelForValue(v); }
function PY(v) { return CH.scales.y.getPixelForValue(v); }

var curvePts = [], i;
for (i = 0; i <= 220; i++) { var cx = TAIL * i / 220; curvePts.push({ x: cx, y: hRaw(cx) }); }
var sampPts = [];
for (i = 0; i <= 11; i++) { var sx = i * 51; sampPts.push({ x: sx, y: hOf(sx) }); }

function kOf(c) {
  if (!c) return 1;
  var w = (c.chartArea && c.chartArea.width) || c.width || 480;
  var h = (c.chartArea && c.chartArea.height) || c.height || 320;
  var k = Math.min(w, h) / 300;
  return Math.max(0.6, Math.min(1.35, k));
}

function ht(ctx, s, x, y, size, align, color, weight) {
  ctx.font = (weight ? weight + ' ' : '') + size.toFixed(1) + 'px ' + SERIF;
  ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2, size * 0.32); ctx.strokeStyle = '#fff';
  ctx.strokeText(s, x, y);
  ctx.fillStyle = color || '#000'; ctx.fillText(s, x, y);
}
function tw(ctx, s, size, weight) {
  ctx.font = (weight ? weight + ' ' : '') + size.toFixed(1) + 'px ' + SERIF;
  return ctx.measureText(s).width;
}
function head(ctx, x, y, ang, size, color) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-size, size * 0.45);
  ctx.lineTo(-size * 0.60, 0); ctx.lineTo(-size, -size * 0.45); ctx.closePath();
  ctx.fillStyle = color; ctx.fill(); ctx.restore();
}
/* long leader arrow with a white halo so it reads clearly over the grid */
function arrow(ctx, x0, y0, x1, y1, k, color) {
  var a = Math.atan2(y1 - y0, x1 - x0), hs = Math.max(7, 10 * k);
  var ex = x1 - Math.cos(a) * hs * 0.7, ey = y1 - Math.sin(a) * hs * 0.7;
  ctx.save(); ctx.lineCap = 'round';
  ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(4, 5 * k);
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.strokeStyle = color; ctx.lineWidth = Math.max(1.5, 2.0 * k);
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.restore();
  head(ctx, x1, y1, a, hs, color);
}

/* ---------- static background ---------- */
function drawGrid(c) {
  var ctx = c.ctx, v;
  ctx.save(); ctx.setLineDash([1, 3]); ctx.lineWidth = 1; ctx.strokeStyle = '#bdbdbd';
  for (v = 100; v <= 600; v += 100) {
    ctx.beginPath(); ctx.moveTo(PX(v), PY(0)); ctx.lineTo(PX(v), PY(320)); ctx.stroke();
  }
  for (v = 50; v <= 300; v += 50) {
    ctx.beginPath(); ctx.moveTo(PX(0), PY(v)); ctx.lineTo(PX(600), PY(v)); ctx.stroke();
  }
  ctx.restore();
}
function drawAxes(ctx, area, k) {
  var y0 = PY(0), x0 = PX(0), s = 8.5 * k, v;
  ctx.save(); ctx.setLineDash([]); ctx.strokeStyle = '#000';
  ctx.lineWidth = Math.max(1.2, 1.7 * k);
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(PX(600) + 12 * k, y0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, PY(320) - 10 * k); ctx.stroke();
  head(ctx, PX(600) + 16 * k, y0, 0, s, '#000');
  head(ctx, x0, PY(320) - 14 * k, -Math.PI / 2, s, '#000');
  ctx.lineWidth = Math.max(1, 1.3 * k);
  for (v = 100; v <= 600; v += 100) {
    ctx.beginPath(); ctx.moveTo(PX(v), y0); ctx.lineTo(PX(v), y0 + 5 * k); ctx.stroke();
  }
  for (v = 50; v <= 300; v += 50) {
    ctx.beginPath(); ctx.moveTo(x0, PY(v)); ctx.lineTo(x0 - 5 * k, PY(v)); ctx.stroke();
  }
  ctx.restore();
}
function drawCurveArrows(ctx, k) {
  var xs = [45, 155, 390, 465], j;
  for (j = 0; j < xs.length; j++) {
    var x = xs[j], d = 5;
    var ax = PX(x), ay = PY(hRaw(x));
    var bx = PX(x + d), by = PY(hRaw(x + d));
    head(ctx, ax, ay, Math.atan2(by - ay, bx - ax), 9.5 * k, TEAL);
  }
  /* descending arrowhead where the path crosses the axis and continues down */
  var t1 = TAIL, t0 = TAIL - 9;
  head(ctx, PX(t1), PY(hRaw(t1)),
    Math.atan2(PY(hRaw(t1)) - PY(hRaw(t0)), PX(t1) - PX(t0)), 10 * k, TEAL);
}
function drawOpenCircle(ctx, k) {
  var cx = PX(195), cy = PY(hOf(195)), r = 6.5 * k;
  ctx.save(); ctx.beginPath(); ctx.arc(cx, cy, r, 0, 6.2832);
  ctx.fillStyle = '#fff'; ctx.fill();
  ctx.lineWidth = Math.max(1.2, 1.8 * k); ctx.strokeStyle = '#e08a2e'; ctx.stroke(); ctx.restore();
}
function drawWall(ctx, k) {
  var w = Math.max(5, 7.5 * k), x = PX(bb.wallX);
  ctx.save(); ctx.fillStyle = WALLRED;
  ctx.fillRect(x - w / 2, PY(bb.wallH), w, PY(0) - PY(bb.wallH));
  ctx.restore();
}

/* ---------- interactive overlays (only after the student acts) ---------- */
function drawMarker(ctx, area, k) {
  var d = bb.dist, y = hOf(d), mx = PX(d), my = PY(y);
  ctx.save();
  ctx.setLineDash([4 * k, 4 * k]); ctx.lineWidth = Math.max(1, 1.2 * k); ctx.strokeStyle = '#9aa0a6';
  ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(mx, PY(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(PX(0), my); ctx.stroke();
  ctx.setLineDash([]);
  ctx.beginPath(); ctx.arc(mx, my, 5.2 * k, 0, 6.2832);
  ctx.fillStyle = TEAL; ctx.fill();
  ctx.lineWidth = 1.6 * k; ctx.strokeStyle = '#fff'; ctx.stroke();

  var txt = '(' + d.toFixed(0) + ' ft, ' + y.toFixed(0) + ' ft)';
  var fs = 11.5 * k, pad = 4.5 * k;
  var bw = tw(ctx, txt, fs) + pad * 2, bh = fs * 1.6;
  var bx = mx + 11 * k, by = my - 12 * k - bh;
  if (bx + bw > area.right - 2) bx = mx - 11 * k - bw;
  if (by < area.top + 2) by = my + 12 * k;
  if (bx < area.left + 2) bx = area.left + 2;
  ctx.fillStyle = 'rgba(255,255,255,0.93)'; ctx.strokeStyle = '#b9c0c7'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.rect(bx, by, bw, bh); ctx.fill(); ctx.stroke();
  ht(ctx, txt, bx + pad, by + bh / 2 + fs * 0.36, fs, 'left', '#123');
  ctx.restore();
}
function drawBall(ctx, k) {
  var cx = PX(bb.flyX), cy = PY(hOf(bb.flyX));
  ctx.save(); ctx.beginPath(); ctx.arc(cx, cy, 6.5 * k, 0, 6.2832);
  ctx.fillStyle = '#fff'; ctx.fill();
  ctx.lineWidth = 2.2 * k; ctx.strokeStyle = TEAL; ctx.stroke(); ctx.restore();
}
function drawTable(ctx, area, k) {
  var fs = Math.max(8, 10 * k), rowH = fs * 1.4;
  var rows = sampPts.slice();
  var w = Math.max(tw(ctx, 'd (ft)', fs, 'bold') * 2 + 30 * k, 78 * k);
  var hgt = rowH * (rows.length + 1) + 9;
  var x1 = area.right - w - 3, y1 = area.top + 3;
  if (y1 + hgt > PY(0) - 4) { rows = rows.filter(function (p, idx) { return idx % 2 === 0; }); hgt = rowH * (rows.length + 1) + 9; }
  ctx.save();
  ctx.fillStyle = 'rgba(255,255,255,0.95)'; ctx.strokeStyle = '#b9c0c7'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.rect(x1, y1, w, hgt); ctx.fill(); ctx.stroke();
  ht(ctx, 'd (ft)', x1 + 8 * k, y1 + rowH, fs, 'left', '#333', 'bold');
  ht(ctx, 'h (ft)', x1 + w - 8 * k, y1 + rowH, fs, 'right', '#333', 'bold');
  ctx.strokeStyle = '#d5dade';
  ctx.beginPath(); ctx.moveTo(x1 + 5, y1 + rowH + 3); ctx.lineTo(x1 + w - 5, y1 + rowH + 3); ctx.stroke();
  for (var r = 0; r < rows.length; r++) {
    var yy = y1 + rowH * (r + 2);
    ht(ctx, rows[r].x.toFixed(0), x1 + 8 * k, yy, fs, 'left', '#123');
    ht(ctx, rows[r].y.toFixed(0), x1 + w - 8 * k, yy, fs, 'right', TEAL);
  }
  ctx.restore();
  return { l: x1, t: y1, r: x1 + w, b: y1 + hgt };
}
function drawClearance(ctx, area, k, tableBox) {
  var landed = bb.wallX > RANGE;
  var hw = landed ? 0 : hOf(bb.wallX);
  var clears = !landed && hw > bb.wallH;
  var col = clears ? GREEN : WALLRED;
  var xl = PX(bb.wallX) + 10 * k;
  var lo = Math.min(hw, bb.wallH), hi = Math.max(hw, bb.wallH);
  ctx.save();
  if (!landed) {
    ctx.setLineDash([5 * k, 4 * k]); ctx.lineWidth = Math.max(1, 1.4 * k); ctx.strokeStyle = col;
    ctx.beginPath(); ctx.moveTo(xl, PY(lo)); ctx.lineTo(xl, PY(hi)); ctx.stroke();
    ctx.setLineDash([]);
    ctx.beginPath();
    ctx.moveTo(xl - 4 * k, PY(lo)); ctx.lineTo(xl + 4 * k, PY(lo));
    ctx.moveTo(xl - 4 * k, PY(hi)); ctx.lineTo(xl + 4 * k, PY(hi));
    ctx.stroke();
    ctx.beginPath(); ctx.arc(PX(bb.wallX), PY(hw), 3.6 * k, 0, 6.2832);
    ctx.fillStyle = col; ctx.fill();
  }
  var gap = Math.abs(hw - bb.wallH);
  var l1 = landed ? 'LANDS SHORT'
    : (clears ? 'CLEARS by ' + gap.toFixed(0) + ' ft' : 'HITS WALL (short by ' + gap.toFixed(0) + ' ft)');
  var l2 = 'h(' + bb.wallX.toFixed(0) + ') = ' + hw.toFixed(0) + ' ft  vs  wall ' + bb.wallH.toFixed(0) + ' ft';
  var f1 = 11.5 * k, f2 = 10 * k, pad = 5 * k;
  var bw = Math.max(tw(ctx, l1, f1, 'bold'), tw(ctx, l2, f2)) + pad * 2;
  var bh = f1 * 1.35 + f2 * 1.4 + pad;
  var bx = PX(bb.wallX) - bw / 2, by = PY(272);
  if (by < area.top + 2) by = area.top + 2;
  if (bx < area.left + 2) bx = area.left + 2;
  if (bx + bw > area.right - 2) bx = area.right - 2 - bw;
  if (tableBox && !(bx + bw < tableBox.l - 6 || bx > tableBox.r + 6 || by + bh < tableBox.t || by > tableBox.b)) {
    bx = Math.max(area.left + 2, tableBox.l - bw - 10);
  }
  ctx.setLineDash([3 * k, 3 * k]); ctx.lineWidth = 1; ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(bx + bw / 2, by + bh);
  ctx.lineTo(xl, PY(hi) - 4 * k); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = clears ? 'rgba(233,248,237,0.96)' : 'rgba(253,235,235,0.96)';
  ctx.strokeStyle = col; ctx.lineWidth = Math.max(1, 1.2 * k);
  ctx.beginPath(); ctx.rect(bx, by, bw, bh); ctx.fill(); ctx.stroke();
  ht(ctx, l1, bx + pad, by + pad + f1, f1, 'left', col, 'bold');
  ht(ctx, l2, bx + pad, by + pad + f1 + f2 * 1.35, f2, 'left', '#333');
  ctx.restore();
}

/* ---------- textbook labels with long, clearly visible leader arrows ------ */
function drawLabels(ctx, area, k) {
  var fs = Math.max(10, 13.5 * k);

  /* ---- 'Trajectory of ball' → open circle on the rising branch ---- */
  var s1 = 'Trajectory of ball';
  var w1 = tw(ctx, s1, fs);
  var tx = PX(86), ty = PY(196);
  if (tx + w1 > area.right - 4) tx = area.right - 4 - w1;
  ht(ctx, s1, tx, ty, fs, 'left', '#000');
  var cx = PX(195), cy = PY(hOf(195)), r = 6.5 * k;
  var e1x = cx - r * 0.95, e1y = cy - r * 1.05;               /* upper-left of circle */
  var a0x = tx + w1 * 0.62, a0y = ty + 6 * k;
  if (a0x > e1x - 14 * k) a0x = e1x - 26 * k;                  /* keep it a real diagonal */
  arrow(ctx, a0x, a0y, e1x, e1y, k, '#000');

  /* ---- 'Position of hitter' → the origin ---- */
  var s2 = 'Position of hitter';
  var w2 = tw(ctx, s2, fs);
  var px2 = PX(88), py2 = PY(36);
  if (px2 + w2 > area.right - 4) px2 = area.right - 4 - w2;
  ht(ctx, s2, px2, py2, fs, 'left', '#000');
  var b0x = px2 - 7 * k, b0y = py2 - 5 * k;
  arrow(ctx, b0x, b0y, PX(4) + 2, PY(3) - 1, k, '#000');

  /* ---- 'Outfield wall' above the red bar ---- */
  var s3 = 'Outfield wall';
  var w3 = tw(ctx, s3, fs);
  var wx = PX(bb.wallX);
  wx = Math.min(Math.max(wx, area.left + w3 / 2 + 4), area.right - w3 / 2 - 4);
  var wy = PY(bb.wallH) - 12 * k;
  if (wy < area.top + fs) wy = area.top + fs;
  ht(ctx, s3, wx, wy, fs, 'center', '#000');
}

/* ---------- chart ---------- */
var cv = document.createElement('canvas');
cv.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(cv);

var overlayPlugin = {
  id: 'bbOverlay',
  beforeDatasetsDraw: function (c) {
    CH = c;
    if (!c.chartArea) return;
    drawGrid(c);
  },
  afterDatasetsDraw: function (c) {
    CH = c;
    if (!c.chartArea) return;
    var ctx = c.ctx, area = c.chartArea, k = kOf(c);
    ctx.save();
    drawAxes(ctx, area, k);
    if (!bb.sampled) drawCurveArrows(ctx, k);
    drawOpenCircle(ctx, k);
    drawWall(ctx, k);
    var tb = bb.sampled ? drawTable(ctx, area, k) : null;
    if (bb.touched) { drawMarker(ctx, area, k); drawClearance(ctx, area, k, tb); }
    if (bb.flying) drawBall(ctx, k);
    drawLabels(ctx, area, k);
    ctx.restore();
  }
};

bb.chart = new Chart(cv.getContext('2d'), {
  type: 'scatter',
  data: {
    datasets: [
      {
        label: 'Trajectory', data: curvePts, showLine: true, borderColor: TEAL,
