          axis.ticks = [0, 50, 100, 150, 200, 250, 300].map(function (v) { return { value: v }; });
        },
        ticks: {
          color: '#000', padding: 6, autoSkip: false,
          font: function (c) { return { family: SERIF, size: Math.round(12.5 * kOf(c.chart)) }; },
          callback: function (v) { return (v % 100 === 0) ? v : ''; }
        },
        title: {
