        }
      }
    }
  },
  plugins: [overlayPlugin]
});
window.__markRendered();

function redraw() { bb.chart.update('none'); updateReadout(); }
function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  if (!bb.touched) {
    el.innerHTML = 'Move a control (or press ▶) to add the marker and the clearance test.';
    return;
  }
  var landed = bb.wallX > RANGE;
  var hw = landed ? 0 : hOf(bb.wallX);
  var verdict = landed ? 'ball lands short' : (hw > bb.wallH ? 'HOME RUN' : 'hits the wall');
  el.innerHTML = 'h(' + bb.dist + ') = ' + hOf(bb.dist).toFixed(1) + ' ft<br>' +
    'At the wall: h(' + bb.wallX + ') = ' + hw.toFixed(1) + ' ft vs ' + bb.wallH + ' ft → <b>' + verdict + '</b>';
}

/* ---------- interaction handlers ---------- */
function update_distanceAlongPath(v) { bb.dist = v; bb.touched = true; redraw(); }
function update_wallPosition(v) { bb.wallX = v; bb.touched = true; redraw(); }
function update_wallHeight(v) { bb.wallH = v; bb.touched = true; redraw(); }
function toggle_viewMode(on) {
  bb.sampled = !!on;
  if (bb.sampled) bb.touched = true;
  bb.chart.data.datasets[0].hidden = bb.sampled;
  bb.chart.data.datasets[1].hidden = !bb.sampled;
  redraw();
}
function trigger_flight() {
  var btn = document.getElementById('flightBtn');
  if (bb.flying) { bb.flying = false; btn.textContent = '▶ Play ball flight'; redraw(); return; }
  bb.flying = true; bb.t0 = performance.now(); bb.flyX = 0;
  btn.textContent = '■ Stop';
  requestAnimationFrame(flightFrame);
}
function flightFrame(now) {
  if (!bb.flying) return;
  var p = (now - bb.t0) / 2600;
  if (p >= 1) {
    bb.flying = false;
    var b = document.getElementById('flightBtn'); if (b) b.textContent = '▶ Play ball flight';
    bb.chart.update('none'); return;
  }
  bb.flyX = p * RANGE;
  bb.chart.update('none');
  requestAnimationFrame(flightFrame);
}

/* ---------- hover / click / drag ---------- */
function mouseData(e) {
  var r = cv.getBoundingClientRect();
  return { mx: e.clientX - r.left, my: e.clientY - r.top };
}
function ready() { return CH && CH.chartArea; }

cv.addEventListener('mousemove', function (e) {
  if (!ready()) return;
  var m = mouseData(e);
  if (bb.drag) {
    var v = CH.scales.x.getValueForPixel(m.mx);
    v = Math.max(0, Math.min(570, Math.round(v / 5) * 5));
    bb.dist = v; bb.touched = true;
    var s = document.getElementById('distanceAlongPathInput');
    if (s) { s.value = v; document.getElementById('distanceAlongPathVal').value = v; }
    redraw();
    showTooltip('(' + v + ' ft, ' + hOf(v).toFixed(0) + ' ft)', e);
    return;
  }
  if (bb.touched && Math.hypot(m.mx - PX(bb.dist), m.my - PY(hOf(bb.dist))) < 13) {
    cv.style.cursor = 'pointer';
    showTooltip('Marker: (' + bb.dist + ' ft, ' + hOf(bb.dist).toFixed(0) + ' ft) — drag me along the arc', e);
    return;
  }
  if (Math.abs(m.mx - PX(bb.wallX)) < 10 && m.my > PY(bb.wallH) - 6 && m.my < PY(0) + 4) {
    cv.style.cursor = 'pointer';
    showTooltip('Outfield wall: ' + bb.wallH + ' ft tall at ' + bb.wallX + ' ft', e);
    return;
  }
  var xv = CH.scales.x.getValueForPixel(m.mx);
  if (xv >= 0 && xv <= RANGE && Math.abs(m.my - PY(hOf(xv))) < 11) {
    cv.style.cursor = 'pointer';
    showTooltip('Trajectory: at ' + xv.toFixed(0) + ' ft the ball is ' + hOf(xv).toFixed(0) + ' ft high', e);
    return;
  }
  cv.style.cursor = 'default';
  hideTooltip();
});
cv.addEventListener('mouseleave', function () { hideTooltip(); bb.drag = false; });
cv.addEventListener('mousedown', function (e) {
  if (!ready()) return;
  var m = mouseData(e);
  var xv = CH.scales.x.getValueForPixel(m.mx);
  if (bb.touched && Math.hypot(m.mx - PX(bb.dist), m.my - PY(hOf(bb.dist))) < 15) { bb.drag = true; return; }
  if (!bb.touched && xv >= 0 && xv <= RANGE && Math.abs(m.my - PY(hOf(xv))) < 12) { bb.drag = true; }
});
window.addEventListener('mouseup', function () { bb.drag = false; });
cv.addEventListener('click', function (e) {
  if (!ready() || bb.drag) return;
  var m = mouseData(e);
  if (Math.abs(m.mx - PX(bb.wallX)) < 12 && m.my > PY(bb.wallH) - 8 && m.my < PY(0) + 4) {
    showPopup('The outfield wall',
      'The wall is just a vertical segment of height ' + bb.wallH + ' ft standing at x = ' + bb.wallX + ' ft. ' +
      'The hit is a home run exactly when h(' + bb.wallX + ') = ' + hOf(bb.wallX).toFixed(0) + ' ft exceeds that wall height. ' +
      'Nothing else about the shape of the curve matters for that single yes/no question.');
    return;
  }
  var xv = CH.scales.x.getValueForPixel(m.mx);
  if (xv >= 0 && xv <= RANGE && Math.abs(m.my - PY(hOf(xv))) < 14) {
    showPopup('One distance, one height',
      'The flight path is the parabola h(x) = 4·155·x·(565 − x)/565², so each distance x has exactly one height. ' +
      'At x = ' + xv.toFixed(0) + ' ft the ball is ' + hOf(xv).toFixed(0) + ' ft above the ground. ' +
      'The vertex near 283 ft is the maximum height, about 155 ft.');
    return;
  }
  showPopup('Reading the figure',
    'Horizontal axis: distance from the hitter; vertical axis: height above the ground — not time. ' +
    'The teal arc records the whole flight at once, from the origin (the hitter) to the landing point near 565 ft. ' +
    'Move the wall sliders to see the clearance badge flip between CLEARS and HITS WALL.');
});

