function applyStep(i, userInit) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  var cb = document.getElementById('viewModeInput');
  if (cb) { cb.checked = (s.state.viewMode === 'Sampled points'); bb.sampled = cb.checked; }
  bb.chart.data.datasets[0].hidden = bb.sampled;
  bb.chart.data.datasets[1].hidden = !bb.sampled;
  bb.wallX = s.state.wallPosition; bb.wallH = s.state.wallHeight; bb.dist = s.state.distanceAlongPath;
  setSlider('wallPosition', s.state.wallPosition);
  setSlider('wallHeight', s.state.wallHeight);
  setSlider('distanceAlongPath', s.state.distanceAlongPath);
  if (userInit) bb.touched = true;
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  redraw();
  if (userInit && s.play && !bb.flying) trigger_flight();
}
function nextStep() { applyStep(stepIdx + 1, true); }
function prevStep() { applyStep(stepIdx - 1, true); }

